svg.script:
(function(){
  var frame = document.getElementById("frame");
  var htmlFile = "slope.html";
  var targetUrl = new URL(htmlFile, document.baseURI).href;
  fetch(targetUrl)
    .then(function(r){
      if(!r.ok) throw new Error("HTTP " + r.status);
      return r.text();
    })
    .then(function(html){
      var baseTag = '<base href="' + new URL("./", targetUrl).href + '">';
      var full = html.includes("<head>") ? html.replace("<head>", "<head>" + baseTag) : (baseTag + html);
      var blob = new Blob([full], { type: "text/html" });
      frame.src = URL.createObjectURL(blob);
    })
    .catch(function(){
      frame.src = targetUrl;
    });
})();
